// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures font is ready before frame 0
const { fontFamily: interFamily } = loadInter();



export type ClosetAnimationProps = Record<string, any>;

const ClosetAnimation: React.FC<ClosetAnimationProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 8,
  text = "Reduce Friction → Better Decisions",
  regularClothesColor = "#334155",
  gymClothesColor = "#10B981",
  personColor = "#F8FAFC",
  rackColor = "#475569",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants
  const regularCount = 6;
  const gymCount = 2;
  const totalItems = regularCount + gymCount;
  const itemWidth = 80;
  const gap = 15;
  const totalWidth = totalItems * itemWidth + (totalItems - 1) * gap;
  
  const rackStartX = width / 2 - totalWidth / 2 - 100; // Shifted left to leave room for person
  const rackY = height / 2 - 80;

  // Animations
  const textOpacity = interpolate(frame, [25, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const textY = interpolate(frame, [25, 45], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const rackLineWidth = interpolate(frame, [0, 25], [0, totalWidth + 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Person Animations
  const personEnterStartFrame = 45;
  const personEnterEndFrame = 80;
  const personStartX = width + 150;
  const personTargetX = rackStartX + totalWidth + 120; // Standing right next to gym clothes

  const personX = interpolate(
    frame,
    [personEnterStartFrame, personEnterEndFrame],
    [personStartX, personTargetX],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  const personOpacity = interpolate(
    frame,
    [personEnterStartFrame, personEnterStartFrame + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Selection Highlights
  const selectionFrame = 85;
  const selectionSpring = spring({
    frame: frame - selectionFrame,
    fps,
    config: { damping: 12 },
  });

  const fadeOutRegular = interpolate(frame, [selectionFrame, selectionFrame + 15], [1, 0.3], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gymLiftY = interpolate(selectionSpring, [0, 1], [0, -15]);
  const gymScale = interpolate(selectionSpring, [0, 1], [1, 1.05]);

  const burstScale = interpolate(frame, [selectionFrame, selectionFrame + 20], [0.5, 2], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const burstOpacity = interpolate(frame, [selectionFrame, selectionFrame + 20], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Title Text */}
      <div
        style={{
          position: "absolute",
          top: height * 0.2,
          width: "100%",
          textAlign: "center",
          fontSize: 64,
          fontWeight: 700,
          color: personColor,
          opacity: textOpacity,
          transform: `translateY(${textY}px)`,
          letterSpacing: "-0.02em",
        }}
      >
        {text}
      </div>

      {/* Closet Rack Line */}
      <div
        style={{
          position: "absolute",
          left: rackStartX - 50,
          top: rackY + 35,
          height: 6,
          width: rackLineWidth,
          backgroundColor: rackColor,
          borderRadius: 3,
        }}
      />

      {/* Clothes */}
      {Array.from({ length: totalItems }).map((_, i) => {
        const isGym = i >= regularCount;
        const color = isGym ? gymClothesColor : regularClothesColor;
        const itemX = rackStartX + i * (itemWidth + gap);
        
        const dropSpring = spring({
          frame: frame - 10 - i * 3,
          fps,
          config: { damping: 14 },
        });

        const dropY = interpolate(dropSpring, [0, 1], [-60, 0]);
        const dropOpacity = interpolate(dropSpring, [0, 0.5], [0, 1], {
          extrapolateRight: "clamp",
        });

        // Apply distinct fading to regular clothes upon selection
        const currentOpacity = isGym ? dropOpacity : dropOpacity * fadeOutRegular;
        // Lift gym clothes on selection
        const currentY = dropY + (isGym ? gymLiftY : 0);
        const currentScale = isGym ? gymScale : 0.95; // regular clothes slightly smaller for depth

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: itemX,
              top: rackY,
              width: itemWidth,
              height: 120,
              opacity: currentOpacity,
              transform: `translateY(${currentY}px) scale(${currentScale})`,
              transformOrigin: "top center",
            }}
          >
            {/* Burst Effect for Gym Clothes */}
            {isGym && frame >= selectionFrame && (
              <div
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "60%",
                  width: 100,
                  height: 100,
                  marginLeft: -50,
                  marginTop: -50,
                  borderRadius: "50%",
                  border: `4px solid ${gymClothesColor}`,
                  transform: `scale(${burstScale})`,
                  opacity: burstOpacity,
                  pointerEvents: "none",
                }}
              />
            )}

            {/* Glowing Shadow for Gym Clothes */}
            {isGym && (
              <div
                style={{
                  position: "absolute",
                  width: "100%",
                  height: "80%",
                  top: "20%",
                  backgroundColor: gymClothesColor,
                  filter: "blur(24px)",
                  opacity: interpolate(selectionSpring, [0, 1], [0, 0.5]),
                  borderRadius: 40,
                }}
              />
            )}

            {/* Hanger & Shirt SVG */}
            <svg width="80" height="120" viewBox="0 0 80 120" style={{ overflow: "visible", position: "relative" }}>
              {/* Hook */}
              <path
                d="M 40 25 C 40 10, 50 10, 50 20 C 50 25, 40 25, 40 35"
                stroke={rackColor}
                fill="none"
                strokeWidth="4"
                strokeLinecap="round"
              />
              {/* Hanger Base */}
              <path
                d="M 15 45 L 40 35 L 65 45"
                stroke={rackColor}
                fill="none"
                strokeWidth="4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              {/* Shirt Body */}
              <path
                d="M 28 42 Q 40 50 52 42 L 72 50 L 67 65 L 55 60 L 55 110 L 25 110 L 25 60 L 13 65 L 8 50 Z"
                fill={color}
              />
            </svg>
          </div>
        );
      })}

      {/* Person Icon */}
      <div
        style={{
          position: "absolute",
          left: personX,
          top: rackY + 50,
          opacity: personOpacity,
          transform: "translate(-50%, -50%)",
        }}
      >
        <svg width="70" height="70" viewBox="0 0 70 70" style={{ overflow: "visible" }}>
          {/* Head */}
          <circle cx="35" cy="20" r="14" fill={personColor} />
          {/* Body */}
          <path d="M 15 65 C 15 45, 55 45, 55 65 Z" fill={personColor} />
          
          {/* Simple highlight ring when selection happens */}
          {frame >= selectionFrame && (
            <circle
              cx="35"
              cy="20"
              r="20"
              fill="none"
              stroke={gymClothesColor}
              strokeWidth="3"
              style={{
                opacity: burstOpacity,
                transform: `scale(${burstScale})`,
                transformOrigin: "35px 20px",
              }}
            />
          )}
        </svg>
      </div>
      
    </AbsoluteFill>
  );
};

export default ClosetAnimation;